#!/usr/bin/env bash
set -Eeuo pipefail

APP_DIR="${APP_DIR:-/opt/todo-assistant}"
STATE_FILE="$APP_DIR/last-good.env"

cd "$APP_DIR"

if [[ ! -f "$STATE_FILE" ]]; then
  echo "ERROR: No known-good release is available for rollback." >&2
  exit 1
fi

# This file must be generated by our deployment script and writable only by root.
# shellcheck disable=SC1090
source "$STATE_FILE"

: "${BACKEND_IMAGE:?Missing previous backend image}"
: "${FRONTEND_IMAGE:?Missing previous frontend image}"

export BACKEND_IMAGE FRONTEND_IMAGE

docker compose -f docker-compose.prod.yml pull
docker compose -f docker-compose.prod.yml up -d --remove-orphans

echo "Previous image versions have been restored."
